<script src="https://unpkg.com/html5-qrcode" type="text/javascript"></script><script>const statusText=document.getElementById('scan-status');const scanner=new Html5QrcodeScanner('reader',{fps:10,qrbox:{width:250,height:250}},false);function onScanSuccess(decodedText){scanner.clear();fetch('{{ route('organizer.attendance.checkin') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body:JSON.stringify({qr_code:decodedText})}).then(async response=>{const data=await response.json();statusText.textContent=data.message+(data.participant?' '+data.participant:'');statusText.className=response.ok?'text-sm text-lime-400 text-center mt-4':'text-sm text-rose-400 text-center mt-4';}).catch(()=>{statusText.textContent='Could not record check-in.';});}scanner.render(onScanSuccess,()=>{});</script>
